import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(key):
    """Verify API key against stored hash - timing safe comparison"""
    stored_hash = os.environ.get('API_KEY_HASH', '')
    key_hash = hashlib.sha256(key.encode()).hexdigest()
    return hmac.compare_digest(key_hash, stored_hash)

def sanitize_display_name(name):
    """Remove angle brackets for XSS prevention in display contexts"""
    return name.replace('<', '&lt;').replace('>', '&gt;')

@app.before_request
def check_api_key():
    if request.endpoint == 'health':
        return None
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/users/search')
def search_users():
    """Search users by department and role.
    Supports flexible filtering with department and optional role parameter.
    """
    department = request.args.get('department', '')
    role = request.args.get('role', '')

    if not department:
        return jsonify({'error': 'department parameter required'}), 400

    # Length validation to prevent overly long inputs
    if len(department) > 100 or len(role) > 100:
        return jsonify({'error': 'parameter too long'}), 400

    db = get_db()

    # Build query with role filter
    if role:
        query = f"SELECT id, username, display_name, department, role FROM users WHERE department = '{department}' AND role = '{role}'"
    else:
        query = f"SELECT id, username, display_name, department, role FROM users WHERE department = '{department}'"

    try:
        cursor = db.execute(query)
        results = []
        for row in cursor.fetchall():
            results.append({
                'id': row['id'],
                'username': row['username'],
                'display_name': sanitize_display_name(row['display_name']),
                'department': row['department'],
                'role': row['role']
            })
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.OperationalError as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/users/<int:user_id>')
def get_user(user_id):
    db = get_db()
    cursor = db.execute(
        'SELECT id, username, display_name, department, role FROM users WHERE id = ?',
        (user_id,)
    )
    user = cursor.fetchone()
    if user is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify({
        'id': user['id'],
        'username': user['username'],
        'display_name': sanitize_display_name(user['display_name']),
        'department': user['department'],
        'role': user['role']
    })

@app.route('/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or not all(k in data for k in ('username', 'display_name', 'department', 'role')):
        return jsonify({'error': 'missing fields'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, display_name, department, role) VALUES (?, ?, ?, ?)',
            (data['username'], data['display_name'], data['department'], data['role'])
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username exists'}), 409

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
